-- the column default of 0, which the game reads as "not computed".
--
-- No ALTER TABLE here on purpose: the column is guaranteed by
-- DataManager::updateDataPackTablesAndColumnsToLatestVersion, and the migration runner
-- throws on any SQLite error, so a duplicate ALTER would abort the whole migration.

